css:
body {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
    background-color: #f0f0f0;
    margin: 0;
}

#game-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    background-color: #800080;
    padding: 20px;
    border-radius: 10px;
    color: #ffffff;
}

#score-display {
    font-size: 24px;
    margin-bottom: 20px;
}

#click-button {
    background-color: #ff0000;
    padding: 15px 30px;
    border: none;
    border-radius: 5px;
    font-size: 18px;
    cursor: pointer;
    margin-bottom: 20px;
    color: #ffffff;
}

#update-menu {
    background-color: #4b0082;
    padding: 20px;
    border-radius: 10px;
    color: #ffffff;
}

.hidden {
    display: none;
}

#resume-button {
    background-color: #ff4500;
    padding: 10px 20px;
    border: none;
    border-radius: 5px;
    font-size: 16px;
    cursor: pointer;
    color: #ffffff;
}

javascript:
var score = 0;
var gamePaused = false;

document.getElementById("click-button").addEventListener("click", function() {
    if (!gamePaused) {
        score += 1;
        document.getElementById("score-display").innerText = "Score: " + score;
        $.ajax({
            type: "POST",
            url: "/skibidi",
            data: JSON.stringify({ score: score }),
            contentType: "application/json",
            success: function(response) {
                console.log("Score sent successfully:", response);
            },
            error: function(error) {
                console.error("Error sending score:", error);
            }
        });
    }
});

document.getElementById("resume-button").addEventListener("click", function() {
    document.getElementById("update-menu").classList.add("hidden");
    gamePaused = false;
});

function showUpdateMenu(updates) {
    document.getElementById("updates").innerText = "Game Updates: " + updates;
    document.getElementById("update-menu").classList.remove("hidden");
    gamePaused = true;
}

